AddLayerButton.def:
({
  name,
  size = 16,
  className = '',
  style = {},
  children
}) => {
  const ready = useIconsReady()

  // If children are provided, render directly (for custom icons)
  if (children) {
    return (
      <svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="currentColor"
        xmlns="http://www.w3.org/2000/svg"
        className={`inline-block ${className}`}
        style={{
          verticalAlign: 'middle',
          ...style
        }}
      >
        {children}
      </svg>
    )
  }

  const dimension = normalizeSize(size)

  // Consumer-registered icons resolve synchronously; the packaged set needs its
  // chunk. resolveIcon checks CUSTOM first, so custom icons paint on first render.
  const svgMarkup = resolveIcon(name)

  if (!svgMarkup) {
    // Not resolved yet. If the packaged chunk is still streaming, hold the layout
    // box so the icon pops in without shifting. (Custom icons never reach here.)
    if (!ready) {
      return (
        <span
          aria-hidden="true"
          className={`inline-flex items-center justify-center ${className}`}
          style={{ width: dimension, height: dimension, lineHeight: 0, ...style }}
        />
      )
    }
    console.warn(`Icon "${name}" not found in icon set`)
    return null
  }

  const sizedMarkup = applySizeToMarkup(svgMarkup, dimension)

  return (
    <span
      className={`inline-flex items-center justify-center ${className}`}
      style={{
        width: dimension,
        height: dimension,
        lineHeight: 0,
        ...style
      }}
      dangerouslySetInnerHTML={{ __html: sizedMarkup }}
    />
  )
}

LayerStack.def:
function rowLabelForLayer(layer) {
  if (layer.name) return layer.name
  if (layer.type === 'text') return layer.text || TYPE_LABELS.text
  if (layer.type === 'shape') {
    return SHAPE_KIND_LABELS[layer.kind ?? 'logo'] ?? TYPE_LABELS.shape
  }
  if (layer.type === 'bool') return BOOL_OP_LABELS[layer.op] ?? TYPE_LABELS.bool
  if (layer.type === 'loop' || layer.type === 'misc') return layer.presetLabel || TYPE_LABELS[layer.type]
  if (layer.type === 'kinetic') return layer.presetLabel || TYPE_LABELS.kinetic
  return TYPE_LABELS[layer.type] ?? layer.type
}

